import React, { useState, useEffect } from "react";
import "./navbar.css";

const PlayerSearch = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const [players, setPlayers] = useState([]);
  const [searchResults, setSearchResults] = useState([]);

  useEffect(() => {
    // Fetching player data (replace URL with actual API endpoint)
    const fetchPlayers = async () => {
      try {
        const response = await fetch("http://localhost:8080/players");
        if (response.ok) {
          const data = await response.json();
          setPlayers(data);
        } else {
          console.error("Failed to fetch players.");
        }
      } catch (error) {
        console.error("Error fetching players:", error);
      }
    };

    fetchPlayers();
  }, []);

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
    const filteredPlayers = players.filter((player) =>
      player.name.toLowerCase().includes(e.target.value.toLowerCase())
    );
    setSearchResults(filteredPlayers);
  };

  const handleFollow = (playerId) => {
    // API call to follow a player (replace URL with actual API endpoint)
    fetch(`http://localhost:8080/follow/${playerId}`, { method: "POST" })
      .then((response) => {
        if (response.ok) {
          alert("بازیکن با موفقیت دنبال شد.");
        } else {
          alert("خطا در دنبال کردن بازیکن.");
        }
      })
      .catch((error) => {
        console.error("Error following player:", error);
      });
  };

  return (
    <div className="main-container">
      <h1>جستجوی بازیکنان</h1>
      <input
        type="text"
        placeholder="نام بازیکن را وارد کنید..."
        value={searchTerm}
        onChange={handleSearch}
        className="search-input"
      />
      <div className="results-container">
        {searchResults.map((player) => (
          <div key={player.id} className="player-card">
            <p>{player.name}</p>
            <button onClick={() => handleFollow(player.id)}>دنبال کردن</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default PlayerSearch;
